patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..459c5a1
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,82 @@
+/**
+ * Reproduction for "files on a different drive are not ignored on Windows".
+ *
+ * Simulates Windows path semantics on any OS by swapping the shared `node:path`
+ * module's functions for `path.win32` (after ESLint and the rule used are loaded,
+ * so Node's module resolution is unaffected; ESLint and @eslint/config-array call
+ * `path.relative` etc. at run time) and by using a Windows-style cwd on drive C:.
+ * Lint targets are passed as text, so no Windows files need to exist.
+ *
+ * Run: node repro/cross-drive-ignore.js
+ */
+/* eslint-disable no-console -- CLI-style repro script */
+"use strict";
+
+const os = require("node:os");
+const path = require("node:path");
+const { ESLint, Linter } = require("../lib/api");
+const { FlatConfigArray } = require("../lib/config/flat-config-array");
+
+const CWD = "C:\\Project";
+const config = { rules: { "no-undef": "error" } };
+const eslintOptions = { overrideConfigFile: true, overrideConfig: config };
+const cases = [
+    { file: "C:\\Project\\foo.js", expectIgnored: false, note: "inside cwd" },
+    { file: "C:\\other\\foo.js", expectIgnored: true, note: "same drive, outside cwd" },
+    { file: "F:\\foo.js", expectIgnored: true, note: "different drive (bug)" }
+];
+
+/**
+ * Formats lint messages compactly.
+ * @param {Object[]} messages Lint messages.
+ * @returns {string} Rule IDs, or the message text for rule-less messages.
+ */
+function summarize(messages) {
+    return JSON.stringify(messages.map(m => m.ruleId ?? m.message));
+}
+
+(async () => {
+
+    // Warm up lazily-required modules (e.g. the no-undef rule) while `path` is still POSIX.
+    new Linter({ configType: "flat" }).verify("foo()", config, "warmup.js");
+    await new ESLint({ ...eslintOptions, cwd: os.tmpdir() }).lintText("foo()", { filePath: path.join(os.tmpdir(), "warmup.js") });
+
+    Object.assign(path, path.win32);
+    process.cwd = () => CWD;
+
+    console.log(`cwd: ${process.cwd()}`);
+    console.log(`path.relative(${JSON.stringify(CWD)}, "F:\\\\foo.js") = ${JSON.stringify(path.relative(CWD, "F:\\foo.js"))}\n`);
+
+    let failed = false;
+
+    for (const { file, expectIgnored, note } of cases) {
+        const configs = new FlatConfigArray([config], { basePath: CWD });
+
+        configs.normalizeSync();
+
+        const status = configs.getConfigStatus(file);
+        const linterMessages = new Linter({ configType: "flat" }).verify("foo()", config, file);
+        const eslint = new ESLint({ ...eslintOptions, cwd: CWD });
+        const pathIgnored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo()", { filePath: file, warnIgnored: true });
+
+        const lintedBy = [linterMessages, result.messages].map(ms => ms.some(m => m.ruleId === "no-undef"));
+        const ok = expectIgnored
+            ? status === "external" && pathIgnored && lintedBy.every(linted => !linted)
+            : status === "matched" && !pathIgnored && lintedBy.every(Boolean);
+
+        failed ||= !ok;
+
+        console.log(`${ok ? "OK  " : "FAIL"} ${file} (${note}) -- expected ${expectIgnored ? "ignored" : "linted"}`);
+        console.log(`     FlatConfigArray#getConfigStatus: ${status}`);
+        console.log(`     Linter#verify:                   ${summarize(linterMessages)}`);
+        console.log(`     ESLint#isPathIgnored:            ${pathIgnored}`);
+        console.log(`     ESLint#lintText:                 ${summarize(result.messages)}`);
+    }
+
+    process.exitCode = failed ? 1 : 0;
+})().catch(error => {
+    console.error(error);
+    process.exitCode = 2;
+});
+/* eslint-enable no-console -- end of repro script */
